// Direct SSR Function for /3d and /3D
const HTML_CONTENT = "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>SPRINGMOON 3D STUDIO | 사진 기반 3D 프린팅 STL 메이커</title>\n  <meta name=\"description\" content=\"사진을 업로드하면 뱀부랩(Bambu Lab) P1S 3D 프린터에 최적화된 애견 목걸이, 네임택, 키링, 리소페인 STL 파일을 즉시 생성하는 전문 3D 스튜디오\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Pretendard:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n  \n  <!-- Three.js & Plugins -->\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js\"></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/exporters/STLExporter.js\"></script>\n  \n  <style>\n    :root {\n      --bg-base: #0b0d14;\n      --bg-surface: #121520;\n      --bg-card: #1a1e2e;\n      --bg-hover: #242a3e;\n      --bg-input: #0e111a;\n      \n      --border-subtle: #262c3f;\n      --border-focus: #3b82f6;\n      \n      --brand-primary: #3b82f6;\n      --brand-gradient: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);\n      --bambu-green: #00ae42;\n      --accent-green: #10b981;\n      --accent-amber: #f59e0b;\n      \n      --text-main: #f8fafc;\n      --text-secondary: #94a3b8;\n      --text-dim: #64748b;\n      \n      --radius-sm: 6px;\n      --radius-md: 10px;\n      --radius-lg: 14px;\n      \n      --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.4);\n      --shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.6);\n      \n      --font-mono: 'JetBrains Mono', monospace;\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;\n      -webkit-font-smoothing: antialiased;\n    }\n\n    body {\n      background-color: var(--bg-base);\n      color: var(--text-main);\n      height: 100vh;\n      display: flex;\n      flex-direction: column;\n      overflow: hidden;\n    }\n\n    /* Header */\n    header {\n      height: 54px;\n      background: var(--bg-surface);\n      border-bottom: 1px solid var(--border-subtle);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 0 20px;\n      flex-shrink: 0;\n      z-index: 10;\n    }\n\n    .brand-area {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .brand-badge {\n      background: var(--brand-gradient);\n      color: white;\n      font-size: 10px;\n      font-weight: 800;\n      padding: 3px 8px;\n      border-radius: var(--radius-sm);\n      letter-spacing: 0.5px;\n    }\n\n    .brand-title {\n      font-size: 15px;\n      font-weight: 700;\n      letter-spacing: -0.3px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .brand-sub {\n      color: var(--text-dim);\n      font-size: 12px;\n      font-weight: 400;\n      border-left: 1px solid var(--border-subtle);\n      padding-left: 10px;\n    }\n\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .btn-header {\n      background: var(--bg-card);\n      border: 1px solid var(--border-subtle);\n      color: var(--text-main);\n      padding: 6px 12px;\n      border-radius: var(--radius-sm);\n      font-size: 12px;\n      font-weight: 500;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      transition: all 0.15s;\n    }\n\n    .btn-header:hover {\n      background: var(--bg-hover);\n      border-color: var(--border-focus);\n    }\n\n    .btn-bambu {\n      background: #008a38;\n      border: 1px solid #00a845;\n      color: white;\n      font-weight: 600;\n    }\n\n    .btn-bambu:hover {\n      background: #00a845;\n    }\n\n    /* Layout */\n    .app-main {\n      flex: 1;\n      display: flex;\n      height: calc(100vh - 54px);\n      overflow: hidden;\n    }\n\n    /* Left Sidebar */\n    .sidebar {\n      width: 440px;\n      background: var(--bg-surface);\n      border-right: 1px solid var(--border-subtle);\n      display: flex;\n      flex-direction: column;\n      overflow-y: auto;\n      flex-shrink: 0;\n      scrollbar-width: thin;\n      scrollbar-color: var(--border-subtle) transparent;\n    }\n\n    .sidebar::-webkit-scrollbar {\n      width: 5px;\n    }\n    .sidebar::-webkit-scrollbar-thumb {\n      background: var(--border-subtle);\n      border-radius: 3px;\n    }\n\n    .panel-section {\n      padding: 16px 20px;\n      border-bottom: 1px solid var(--border-subtle);\n    }\n\n    .section-title {\n      font-size: 12px;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.8px;\n      color: var(--text-secondary);\n      margin-bottom: 12px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n    }\n\n    .section-title .badge {\n      font-size: 10px;\n      font-weight: 600;\n      padding: 2px 6px;\n      border-radius: 4px;\n      background: var(--bg-hover);\n      color: var(--text-dim);\n    }\n\n    /* Presets */\n    .preset-grid {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 6px;\n      margin-bottom: 8px;\n    }\n\n    .preset-btn {\n      background: var(--bg-card);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      padding: 8px 6px;\n      text-align: center;\n      cursor: pointer;\n      transition: all 0.15s;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 4px;\n    }\n\n    .preset-btn:hover {\n      background: var(--bg-hover);\n      border-color: var(--border-focus);\n    }\n\n    .preset-btn.active {\n      background: rgba(59, 130, 246, 0.18);\n      border-color: var(--brand-primary);\n    }\n\n    .preset-btn .icon {\n      font-size: 18px;\n    }\n\n    .preset-btn .label {\n      font-size: 11px;\n      font-weight: 600;\n      color: var(--text-main);\n    }\n\n    /* Upload Zone */\n    .upload-zone {\n      border: 2px dashed var(--border-subtle);\n      background: var(--bg-card);\n      border-radius: var(--radius-md);\n      padding: 16px;\n      text-align: center;\n      cursor: pointer;\n      transition: all 0.2s;\n      position: relative;\n    }\n\n    .upload-zone:hover, .upload-zone.dragover {\n      border-color: var(--brand-primary);\n      background: rgba(59, 130, 246, 0.06);\n    }\n\n    .upload-zone input[type=\"file\"] {\n      position: absolute;\n      top: 0; left: 0; width: 100%; height: 100%;\n      opacity: 0;\n      cursor: pointer;\n    }\n\n    .upload-icon {\n      font-size: 24px;\n      margin-bottom: 4px;\n      color: var(--brand-primary);\n    }\n\n    .upload-text {\n      font-size: 12px;\n      font-weight: 600;\n      color: var(--text-main);\n    }\n\n    .upload-sub {\n      font-size: 11px;\n      color: var(--text-dim);\n      margin-top: 2px;\n    }\n\n    .preview-thumb-area {\n      display: none;\n      align-items: center;\n      gap: 12px;\n      background: var(--bg-input);\n      padding: 8px 12px;\n      border-radius: var(--radius-sm);\n      margin-top: 10px;\n      border: 1px solid var(--border-subtle);\n    }\n\n    .preview-thumb {\n      width: 44px;\n      height: 44px;\n      object-fit: cover;\n      border-radius: 4px;\n      border: 1px solid var(--border-subtle);\n    }\n\n    .preview-info {\n      flex: 1;\n      font-size: 12px;\n    }\n\n    .preview-info .filename {\n      font-weight: 600;\n      color: var(--text-main);\n      white-space: nowrap;\n      overflow: hidden;\n      text-overflow: ellipsis;\n      max-width: 200px;\n    }\n\n    .preview-info .dimensions {\n      color: var(--text-dim);\n      font-family: var(--font-mono);\n      font-size: 11px;\n      margin-top: 2px;\n    }\n\n    /* Form Controls */\n    .control-group {\n      margin-bottom: 12px;\n    }\n\n    .control-group:last-child {\n      margin-bottom: 0;\n    }\n\n    .control-label {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      font-size: 12px;\n      font-weight: 600;\n      color: var(--text-secondary);\n      margin-bottom: 5px;\n    }\n\n    .control-val {\n      font-family: var(--font-mono);\n      font-size: 12px;\n      color: var(--brand-primary);\n      font-weight: 600;\n    }\n\n    .control-desc {\n      font-size: 11px;\n      color: var(--text-dim);\n      margin-top: 3px;\n    }\n\n    .slider-range {\n      -webkit-appearance: none;\n      width: 100%;\n      height: 5px;\n      border-radius: 3px;\n      background: var(--bg-input);\n      outline: none;\n      border: 1px solid var(--border-subtle);\n    }\n\n    .slider-range::-webkit-slider-thumb {\n      -webkit-appearance: none;\n      appearance: none;\n      width: 14px;\n      height: 14px;\n      border-radius: 50%;\n      background: var(--brand-primary);\n      cursor: pointer;\n      box-shadow: 0 0 8px rgba(59, 130, 246, 0.5);\n      border: 2px solid white;\n    }\n\n    .segmented-control {\n      display: flex;\n      background: var(--bg-input);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      padding: 2px;\n      gap: 2px;\n    }\n\n    .seg-btn {\n      flex: 1;\n      background: transparent;\n      border: none;\n      color: var(--text-secondary);\n      font-size: 11px;\n      font-weight: 500;\n      padding: 5px 6px;\n      border-radius: 4px;\n      cursor: pointer;\n      transition: all 0.15s;\n      text-align: center;\n      white-space: nowrap;\n    }\n\n    .seg-btn:hover {\n      color: var(--text-main);\n    }\n\n    .seg-btn.active {\n      background: var(--brand-primary);\n      color: white;\n      font-weight: 600;\n    }\n\n    .toggle-row {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 5px 0;\n    }\n\n    .toggle-label {\n      font-size: 12px;\n      font-weight: 500;\n      color: var(--text-main);\n    }\n\n    .switch {\n      position: relative;\n      display: inline-block;\n      width: 36px;\n      height: 20px;\n    }\n\n    .switch input {\n      opacity: 0;\n      width: 0;\n      height: 0;\n    }\n\n    .slider-switch {\n      position: absolute;\n      cursor: pointer;\n      top: 0; left: 0; right: 0; bottom: 0;\n      background-color: var(--bg-input);\n      border: 1px solid var(--border-subtle);\n      transition: .2s;\n      border-radius: 20px;\n    }\n\n    .slider-switch:before {\n      position: absolute;\n      content: \"\";\n      height: 14px;\n      width: 14px;\n      left: 2px;\n      bottom: 2px;\n      background-color: var(--text-dim);\n      transition: .2s;\n      border-radius: 50%;\n    }\n\n    input:checked + .slider-switch {\n      background-color: var(--brand-primary);\n      border-color: var(--brand-primary);\n    }\n\n    input:checked + .slider-switch:before {\n      transform: translateX(16px);\n      background-color: white;\n    }\n\n    .text-input {\n      width: 100%;\n      background: var(--bg-input);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      padding: 7px 10px;\n      color: var(--text-main);\n      font-size: 12px;\n      outline: none;\n      transition: border-color 0.15s;\n    }\n\n    .text-input:focus {\n      border-color: var(--brand-primary);\n    }\n\n    /* Right Viewport Area */\n    .viewport-container {\n      flex: 1;\n      position: relative;\n      background: radial-gradient(circle at center, #161924 0%, #08090e 100%);\n      display: flex;\n      flex-direction: column;\n    }\n\n    #canvas-wrapper {\n      width: 100%;\n      height: 100%;\n      display: block;\n    }\n\n    /* Overlays */\n    .vp-top-bar {\n      position: absolute;\n      top: 14px;\n      left: 16px;\n      right: 16px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      pointer-events: none;\n    }\n\n    .vp-badge-group {\n      display: flex;\n      gap: 8px;\n      pointer-events: auto;\n    }\n\n    .vp-pill {\n      background: rgba(18, 21, 32, 0.85);\n      backdrop-filter: blur(8px);\n      border: 1px solid rgba(255, 255, 255, 0.08);\n      padding: 5px 12px;\n      border-radius: 20px;\n      font-size: 11px;\n      font-weight: 600;\n      color: var(--text-main);\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      box-shadow: var(--shadow-sm);\n    }\n\n    .vp-pill .dot {\n      width: 7px;\n      height: 7px;\n      border-radius: 50%;\n      background: var(--accent-green);\n    }\n\n    .vp-controls {\n      display: flex;\n      gap: 6px;\n      pointer-events: auto;\n    }\n\n    .vp-btn {\n      background: rgba(18, 21, 32, 0.85);\n      backdrop-filter: blur(8px);\n      border: 1px solid rgba(255, 255, 255, 0.08);\n      color: var(--text-main);\n      padding: 5px 10px;\n      border-radius: var(--radius-sm);\n      font-size: 11px;\n      font-weight: 500;\n      cursor: pointer;\n      transition: all 0.15s;\n    }\n\n    .vp-btn:hover {\n      background: var(--bg-hover);\n      border-color: var(--border-focus);\n    }\n\n    .vp-btn.active {\n      background: var(--brand-primary);\n      color: white;\n      border-color: var(--brand-primary);\n    }\n\n    /* Bottom Bar */\n    .vp-bottom-bar {\n      position: absolute;\n      bottom: 16px;\n      left: 16px;\n      right: 16px;\n      background: rgba(18, 21, 32, 0.92);\n      backdrop-filter: blur(12px);\n      border: 1px solid rgba(255, 255, 255, 0.1);\n      border-radius: var(--radius-lg);\n      padding: 12px 18px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      box-shadow: var(--shadow-lg);\n      pointer-events: auto;\n    }\n\n    .model-stats {\n      display: flex;\n      align-items: center;\n      gap: 18px;\n    }\n\n    .stat-item {\n      display: flex;\n      flex-direction: column;\n    }\n\n    .stat-label {\n      font-size: 10px;\n      text-transform: uppercase;\n      letter-spacing: 0.6px;\n      color: var(--text-dim);\n    }\n\n    .stat-value {\n      font-family: var(--font-mono);\n      font-size: 12px;\n      font-weight: 700;\n      color: var(--text-main);\n      margin-top: 1px;\n    }\n\n    .export-actions {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .btn-export-stl {\n      background: var(--brand-gradient);\n      color: white;\n      border: none;\n      padding: 9px 20px;\n      border-radius: var(--radius-md);\n      font-size: 13px;\n      font-weight: 700;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      box-shadow: 0 4px 16px rgba(59, 130, 246, 0.4);\n      transition: all 0.2s;\n    }\n\n    .btn-export-stl:hover {\n      transform: translateY(-1px);\n      box-shadow: 0 6px 20px rgba(59, 130, 246, 0.6);\n    }\n\n    /* Bambu Modal */\n    .modal-overlay {\n      display: none;\n      position: fixed;\n      top: 0; left: 0; width: 100%; height: 100%;\n      background: rgba(0, 0, 0, 0.75);\n      backdrop-filter: blur(4px);\n      z-index: 100;\n      align-items: center;\n      justify-content: center;\n    }\n\n    .modal-card {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-lg);\n      width: 520px;\n      max-width: 90%;\n      padding: 22px;\n      box-shadow: var(--shadow-lg);\n    }\n\n    .modal-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 14px;\n    }\n\n    .modal-title {\n      font-size: 16px;\n      font-weight: 700;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .modal-close {\n      background: transparent;\n      border: none;\n      color: var(--text-dim);\n      font-size: 20px;\n      cursor: pointer;\n    }\n\n    .guide-box {\n      background: var(--bg-input);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      padding: 12px;\n      margin-bottom: 14px;\n      font-size: 12px;\n      line-height: 1.6;\n    }\n\n    .guide-item {\n      display: flex;\n      justify-content: space-between;\n      padding: 5px 0;\n      border-bottom: 1px solid var(--border-subtle);\n    }\n\n    .guide-item:last-child {\n      border-bottom: none;\n    }\n\n    .guide-key {\n      color: var(--text-secondary);\n    }\n\n    .guide-val {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: var(--accent-green);\n    }\n\n    .hint-chip {\n      display: inline-flex;\n      align-items: center;\n      gap: 4px;\n      background: rgba(59, 130, 246, 0.1);\n      color: #93c5fd;\n      padding: 3px 8px;\n      border-radius: 4px;\n      font-size: 11px;\n      margin-top: 5px;\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Top Bar -->\n  <header>\n    <div class=\"brand-area\">\n      <span class=\"brand-badge\">P1S 3D ENGINE</span>\n      <h1 class=\"brand-title\">SPRINGMOON 3D STUDIO</h1>\n      <span class=\"brand-sub\">반려견 목걸이 & 키링 STL 메이커</span>\n    </div>\n    <div class=\"header-actions\">\n      <button class=\"btn-header\" onclick=\"openBambuGuide()\">\n        <span>🐼</span> 뱀부 P1S 최적 세팅 가이드\n      </button>\n      <button class=\"btn-header\" onclick=\"resetDefaults()\">\n        <span>🔄</span> 초기화\n      </button>\n      <button class=\"btn-header btn-bambu\" onclick=\"exportSTL()\">\n        <span>⬇️</span> STL 다운로드\n      </button>\n    </div>\n  </header>\n\n  <!-- Main Workspace -->\n  <main class=\"app-main\">\n    \n    <!-- Sidebar -->\n    <aside class=\"sidebar\">\n      \n      <!-- 1. Presets -->\n      <div class=\"panel-section\">\n        <div class=\"section-title\">\n          <span>1. 맞춤형 프리셋</span>\n          <span class=\"badge\">원클릭</span>\n        </div>\n        <div class=\"preset-grid\">\n          <div class=\"preset-btn active\" onclick=\"applyPreset('pet-circle')\">\n            <span class=\"icon\">🐶</span>\n            <span class=\"label\">원형 목걸이</span>\n          </div>\n          <div class=\"preset-btn\" onclick=\"applyPreset('dog-bone')\">\n            <span class=\"icon\">🦴</span>\n            <span class=\"label\">뼈다귀 네임택</span>\n          </div>\n          <div class=\"preset-btn\" onclick=\"applyPreset('heart-tag')\">\n            <span class=\"icon\">💖</span>\n            <span class=\"label\">하트 펜던트</span>\n          </div>\n          <div class=\"preset-btn\" onclick=\"applyPreset('lithophane')\">\n            <span class=\"icon\">🖼️</span>\n            <span class=\"label\">미니 리소페인</span>\n          </div>\n          <div class=\"preset-btn\" onclick=\"applyPreset('rect-tag')\">\n            <span class=\"icon\">🏷️</span>\n            <span class=\"label\">사각 키링</span>\n          </div>\n          <div class=\"preset-btn\" onclick=\"applyPreset('high-relief')\">\n            <span class=\"icon\">👑</span>\n            <span class=\"label\">고양각 입체</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- 2. Image Upload -->\n      <div class=\"panel-section\">\n        <div class=\"section-title\">\n          <span>2. 사진 업로드 & 명암 조절</span>\n          <span class=\"badge\">IMAGE</span>\n        </div>\n\n        <div class=\"upload-zone\" id=\"drop-zone\">\n          <input type=\"file\" id=\"image-upload\" accept=\"image/*\" onchange=\"handleImageUpload(event)\">\n          <div class=\"upload-icon\">📷</div>\n          <div class=\"upload-text\">사진을 드래그하거나 클릭하여 업로드</div>\n          <div class=\"upload-sub\">JPG, PNG, WebP 지원 (초경량 변환)</div>\n        </div>\n\n        <div class=\"preview-thumb-area\" id=\"thumb-area\">\n          <img id=\"image-thumb\" class=\"preview-thumb\" src=\"\" alt=\"Thumbnail\">\n          <div class=\"preview-info\">\n            <div class=\"filename\" id=\"thumb-filename\">dog_photo.jpg</div>\n            <div class=\"dimensions\" id=\"thumb-dimensions\">512 x 512 px</div>\n          </div>\n          <button class=\"btn-header\" style=\"padding: 3px 8px; font-size: 11px;\" onclick=\"loadSampleImage()\">샘플 로드</button>\n        </div>\n\n        <div style=\"margin-top: 12px;\">\n          <div class=\"control-group\">\n            <div class=\"control-label\">\n              <span>명암 대비 (Contrast)</span>\n              <span class=\"control-val\" id=\"val-contrast\">1.2x</span>\n            </div>\n            <input type=\"range\" class=\"slider-range\" id=\"param-contrast\" min=\"0.5\" max=\"2.5\" step=\"0.1\" value=\"1.2\" oninput=\"debouncedUpdate()\">\n          </div>\n\n          <div class=\"control-group\">\n            <div class=\"control-label\">\n              <span>표면 스무딩 (노이즈 제거)</span>\n              <span class=\"control-val\" id=\"val-smooth\">1.0</span>\n            </div>\n            <input type=\"range\" class=\"slider-range\" id=\"param-smooth\" min=\"0\" max=\"4\" step=\"0.5\" value=\"1.0\" oninput=\"debouncedUpdate()\">\n            <div class=\"control-desc\">값을 올리면 거친 노이즈가 완화되어 FDM 출력 시 표면이 매끄러워집니다.</div>\n          </div>\n\n          <div class=\"toggle-row\">\n            <span class=\"toggle-label\">명암 반전 (Invert Height)</span>\n            <label class=\"switch\">\n              <input type=\"checkbox\" id=\"param-invert\" onchange=\"debouncedUpdate()\">\n              <span class=\"slider-switch\"></span>\n            </label>\n          </div>\n\n          <div class=\"toggle-row\">\n            <span class=\"toggle-label\">배경 자동 투명화 (누끼)</span>\n            <label class=\"switch\">\n              <input type=\"checkbox\" id=\"param-remove-bg\" checked onchange=\"debouncedUpdate()\">\n              <span class=\"slider-switch\"></span>\n            </label>\n          </div>\n        </div>\n      </div>\n\n      <!-- 3. Base Shape & Dimensions -->\n      <div class=\"panel-section\">\n        <div class=\"section-title\">\n          <span>3. 베이스 형태 & 치수 (mm)</span>\n          <span class=\"badge\">P1S SPEC</span>\n        </div>\n\n        <div class=\"control-group\">\n          <div class=\"control-label\">바닥 플레이트 모양</div>\n          <div class=\"segmented-control\">\n            <button class=\"seg-btn active\" id=\"shape-circle\" onclick=\"setShape('circle')\">원형</button>\n            <button class=\"seg-btn\" id=\"shape-rounded\" onclick=\"setShape('rounded')\">둥근 사각</button>\n            <button class=\"seg-btn\" id=\"shape-bone\" onclick=\"setShape('bone')\">뼈다귀</button>\n            <button class=\"seg-btn\" id=\"shape-heart\" onclick=\"setShape('heart')\">하트</button>\n            <button class=\"seg-btn\" id=\"shape-rect\" onclick=\"setShape('rect')\">직사각</button>\n          </div>\n        </div>\n\n        <div class=\"control-group\">\n          <div class=\"control-label\">\n            <span>가로 직경 / 크기 (Width)</span>\n            <span class=\"control-val\" id=\"val-width\">40 mm</span>\n          </div>\n          <input type=\"range\" class=\"slider-range\" id=\"param-width\" min=\"20\" max=\"90\" step=\"1\" value=\"40\" oninput=\"debouncedUpdate()\">\n        </div>\n\n        <div class=\"control-group\">\n          <div class=\"control-label\">\n            <span>바닥판 베이스 두께 (Base Height)</span>\n            <span class=\"control-val\" id=\"val-base-thick\">2.0 mm</span>\n          </div>\n          <input type=\"range\" class=\"slider-range\" id=\"param-base-thick\" min=\"1.0\" max=\"5.0\" step=\"0.2\" value=\"2.0\" oninput=\"debouncedUpdate()\">\n          <div class=\"control-desc\">권장: 1.8 ~ 2.4mm (목걸이 체결 시 튼튼함)</div>\n        </div>\n\n        <div class=\"control-group\">\n          <div class=\"control-label\">\n            <span>릴리프 돌출 높이 (Relief Height)</span>\n            <span class=\"control-val\" id=\"val-relief-height\">1.4 mm</span>\n          </div>\n          <input type=\"range\" class=\"slider-range\" id=\"param-relief-height\" min=\"0.4\" max=\"4.0\" step=\"0.1\" value=\"1.4\" oninput=\"debouncedUpdate()\">\n        </div>\n\n        <div class=\"control-group\">\n          <div class=\"control-label\">\n            <span>외곽 테두리 베젤 (Border Rim)</span>\n            <span class=\"control-val\" id=\"val-rim-height\">0.8 mm</span>\n          </div>\n          <input type=\"range\" class=\"slider-range\" id=\"param-rim-height\" min=\"0\" max=\"2.5\" step=\"0.2\" value=\"0.8\" oninput=\"debouncedUpdate()\">\n        </div>\n      </div>\n\n      <!-- 4. Keyring Loop -->\n      <div class=\"panel-section\">\n        <div class=\"section-title\">\n          <span>4. 목걸이 줄 / 키링 고리</span>\n          <span class=\"badge\">LOOP</span>\n        </div>\n\n        <div class=\"control-group\">\n          <div class=\"control-label\">고리 위치</div>\n          <div class=\"segmented-control\">\n            <button class=\"seg-btn active\" id=\"loop-top\" onclick=\"setLoopPos('top')\">상단 중앙</button>\n            <button class=\"seg-btn\" id=\"loop-both\" onclick=\"setLoopPos('both')\">양쪽 고리</button>\n            <button class=\"seg-btn\" id=\"loop-none\" onclick=\"setLoopPos('none')\">고리 없음</button>\n          </div>\n        </div>\n\n        <div class=\"control-group\" id=\"loop-params-group\">\n          <div class=\"control-label\">\n            <span>고리 구멍 내경 (Hole Dia)</span>\n            <span class=\"control-val\" id=\"val-hole-dia\">3.5 mm</span>\n          </div>\n          <input type=\"range\" class=\"slider-range\" id=\"param-hole-dia\" min=\"2.0\" max=\"6.0\" step=\"0.5\" value=\"3.5\" oninput=\"debouncedUpdate()\">\n          <div class=\"hint-chip\">💡 목걸이 오링(O-Ring) 체결 시 3.5mm 추천</div>\n        </div>\n      </div>\n\n      <!-- 5. Back Engraving -->\n      <div class=\"panel-section\">\n        <div class=\"section-title\">\n          <span>5. 각인 텍스트 (이름 & 전화번호)</span>\n          <span class=\"badge\">TEXT</span>\n        </div>\n\n        <div class=\"control-group\">\n          <div class=\"toggle-row\">\n            <span class=\"toggle-label\">텍스트 각인 활성화</span>\n            <label class=\"switch\">\n              <input type=\"checkbox\" id=\"param-text-toggle\" checked onchange=\"debouncedUpdate()\">\n              <span class=\"slider-switch\"></span>\n            </label>\n          </div>\n        </div>\n\n        <div id=\"text-controls\">\n          <div class=\"control-group\">\n            <div class=\"control-label\">반려견 이름 (Line 1)</div>\n            <input type=\"text\" class=\"text-input\" id=\"param-text-line1\" value=\"초코 (CHOCO)\" placeholder=\"예: 초코\" oninput=\"debouncedUpdate()\">\n          </div>\n          <div class=\"control-group\">\n            <div class=\"control-label\">연락처 / 등록번호 (Line 2)</div>\n            <input type=\"text\" class=\"text-input\" id=\"param-text-line2\" value=\"010-1234-5678\" placeholder=\"예: 010-1234-5678\" oninput=\"debouncedUpdate()\">\n          </div>\n        </div>\n      </div>\n\n    </aside>\n\n    <!-- 3D Viewport -->\n    <section class=\"viewport-container\">\n      \n      <div class=\"vp-top-bar\">\n        <div class=\"vp-badge-group\">\n          <div class=\"vp-pill\">\n            <div class=\"dot\"></div>\n            <span>Bambu Lab P1S 가상 베드 (256x256mm)</span>\n          </div>\n          <div class=\"vp-pill\">\n            <span>실시간 3D 렌더러</span>\n          </div>\n        </div>\n\n        <div class=\"vp-controls\">\n          <button class=\"vp-btn active\" id=\"mat-pla\" onclick=\"setMaterial('pla')\">Matt PLA</button>\n          <button class=\"vp-btn\" id=\"mat-gold\" onclick=\"setMaterial('gold')\">Silk Gold</button>\n          <button class=\"vp-btn\" id=\"mat-litho\" onclick=\"setMaterial('litho')\">Lithophane</button>\n          <button class=\"vp-btn\" id=\"mat-wire\" onclick=\"toggleWireframe()\">와이어프레임</button>\n          <button class=\"vp-btn\" onclick=\"resetCamera()\">카메라 리셋</button>\n        </div>\n      </div>\n\n      <div id=\"canvas-wrapper\"></div>\n\n      <div class=\"vp-bottom-bar\">\n        <div class=\"model-stats\">\n          <div class=\"stat-item\">\n            <span class=\"stat-label\">외경 치수 (X x Y x Z)</span>\n            <span class=\"stat-value\" id=\"stat-dimensions\">40.0 x 40.0 x 3.4 mm</span>\n          </div>\n          <div class=\"stat-item\">\n            <span class=\"stat-label\">예상 출력 시간</span>\n            <span class=\"stat-value\" id=\"stat-time\">~15분 (P1S)</span>\n          </div>\n          <div class=\"stat-item\">\n            <span class=\"stat-label\">예상 필라멘트 무게</span>\n            <span class=\"stat-value\" id=\"stat-weight\">~4.5 g</span>\n          </div>\n          <div class=\"stat-item\">\n            <span class=\"stat-label\">Bambu 호환성</span>\n            <span class=\"stat-value\" style=\"color: var(--accent-green);\">100% Solid Mesh</span>\n          </div>\n        </div>\n\n        <div class=\"export-actions\">\n          <button class=\"btn-export-stl\" onclick=\"exportSTL()\">\n            <span>📥</span> Bambu P1S용 STL 내보내기\n          </button>\n        </div>\n      </div>\n\n    </section>\n\n  </main>\n\n  <!-- Bambu Guide Modal -->\n  <div class=\"modal-overlay\" id=\"guide-modal\" onclick=\"closeBambuGuide(event)\">\n    <div class=\"modal-card\" onclick=\"event.stopPropagation()\">\n      <div class=\"modal-header\">\n        <h3 class=\"modal-title\"><span>🐼</span> 뱀부랩 P1S / Bambu Studio 최적 세팅</h3>\n        <button class=\"modal-close\" onclick=\"closeBambuGuide()\">&times;</button>\n      </div>\n\n      <div class=\"guide-box\">\n        <div class=\"guide-item\">\n          <span class=\"guide-key\">프린터 & 노즐</span>\n          <span class=\"guide-val\">Bambu Lab P1S (0.4mm 또는 0.2mm Nozzle)</span>\n        </div>\n        <div class=\"guide-item\">\n          <span class=\"guide-key\">레이어 높이 (Layer Height)</span>\n          <span class=\"guide-val\">0.12mm (High Quality) 또는 0.16mm</span>\n        </div>\n        <div class=\"guide-item\">\n          <span class=\"guide-key\">첫 레이어 높이 (First Layer)</span>\n          <span class=\"guide-val\">0.20mm</span>\n        </div>\n        <div class=\"guide-item\">\n          <span class=\"guide-key\">벽 생성 (Wall Loops)</span>\n          <span class=\"guide-val\">3 ~ 4 Loops</span>\n        </div>\n        <div class=\"guide-item\">\n          <span class=\"guide-key\">채우기 밀도 (Infill Density)</span>\n          <span class=\"guide-val\">100% (Solid 견고함)</span>\n        </div>\n        <div class=\"guide-item\">\n          <span class=\"guide-key\">다림질 (Ironing) ★핵심</span>\n          <span class=\"guide-val\">모든 상단 표면 (All Top Surfaces) 활성화</span>\n        </div>\n      </div>\n\n      <div style=\"font-size: 12px; color: var(--text-secondary); line-height: 1.5; margin-bottom: 16px;\">\n        💡 <strong>출력 마감 팁:</strong> Bambu Studio에서 상단 표면 다림질(Ironing)을 켜주시면, 0.4mm 노즐이 뜨거운 열로 표면을 매끄럽게 문질러 사진 릴리프와 텍스트가 사출 성형품처럼 깔끔하게 인쇄됩니다.\n      </div>\n\n      <div style=\"text-align: right;\">\n        <button class=\"btn-header btn-bambu\" style=\"display: inline-flex;\" onclick=\"closeBambuGuide()\">확인 완료</button>\n      </div>\n    </div>\n  </div>\n\n  <canvas id=\"proc-canvas\" style=\"display: none;\"></canvas>\n\n  <script>\n    // Global State\n    let scene, camera, renderer, controls;\n    let mainMeshGroup = null;\n    let currentShape = 'circle';\n    let currentLoopPos = 'top';\n    let currentMaterialMode = 'pla';\n    let isWireframe = false;\n    let loadedImage = null;\n    let heightmapData = null;\n    let debounceTimer = null;\n    const gridRes = 140; // High speed & smooth memory optimization\n\n    function init3D() {\n      const container = document.getElementById('canvas-wrapper');\n      \n      // Scene\n      scene = new THREE.Scene();\n      scene.background = new THREE.Color(0x0e111a);\n\n      // Camera\n      camera = new THREE.PerspectiveCamera(45, container.clientWidth / container.clientHeight, 0.1, 1000);\n      camera.position.set(0, -55, 60);\n\n      // Renderer (Ultra lightweight & performant)\n      renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: \"high-performance\" });\n      renderer.setSize(container.clientWidth, container.clientHeight);\n      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n      renderer.shadowMap.enabled = true;\n      renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n      container.appendChild(renderer.domElement);\n\n      // OrbitControls\n      controls = new THREE.OrbitControls(camera, renderer.domElement);\n      controls.enableDamping = true;\n      controls.dampingFactor = 0.05;\n      controls.maxPolarAngle = Math.PI / 2 + 0.1;\n      controls.minDistance = 15;\n      controls.maxDistance = 250;\n\n      // Lights\n      const ambientLight = new THREE.AmbientLight(0xffffff, 0.65);\n      scene.add(ambientLight);\n\n      const dirLight = new THREE.DirectionalLight(0xffffff, 0.85);\n      dirLight.position.set(45, -50, 75);\n      dirLight.castShadow = true;\n      dirLight.shadow.mapSize.width = 1024;\n      dirLight.shadow.mapSize.height = 1024;\n      scene.add(dirLight);\n\n      const backLight = new THREE.DirectionalLight(0x7090ff, 0.35);\n      backLight.position.set(-45, 50, 40);\n      scene.add(backLight);\n\n      // Virtual Bambu P1S Bed\n      createBambuBed();\n\n      // Main Group\n      mainMeshGroup = new THREE.Group();\n      scene.add(mainMeshGroup);\n\n      window.addEventListener('resize', onWindowResize);\n      loadSampleImage();\n      animate();\n    }\n\n    function createBambuBed() {\n      const bedGeo = new THREE.PlaneGeometry(256, 256);\n      const bedMat = new THREE.MeshStandardMaterial({\n        color: 0x1d212d,\n        roughness: 0.85,\n        metalness: 0.15\n      });\n      const bed = new THREE.Mesh(bedGeo, bedMat);\n      bed.position.z = -0.1;\n      bed.receiveShadow = true;\n      scene.add(bed);\n\n      const grid = new THREE.GridHelper(256, 25.6, 0x3b82f6, 0x242a3a);\n      grid.rotation.x = Math.PI / 2;\n      grid.position.z = 0;\n      scene.add(grid);\n    }\n\n    function onWindowResize() {\n      const container = document.getElementById('canvas-wrapper');\n      camera.aspect = container.clientWidth / container.clientHeight;\n      camera.updateProjectionMatrix();\n      renderer.setSize(container.clientWidth, container.clientHeight);\n    }\n\n    function animate() {\n      requestAnimationFrame(animate);\n      controls.update();\n      renderer.render(scene, camera);\n    }\n\n    function debouncedUpdate() {\n      if (debounceTimer) clearTimeout(debounceTimer);\n      debounceTimer = setTimeout(() => {\n        updateModel();\n      }, 50);\n    }\n\n    function handleImageUpload(e) {\n      const file = e.target.files[0];\n      if (!file) return;\n\n      const reader = new FileReader();\n      reader.onload = function(evt) {\n        const img = new Image();\n        img.onload = function() {\n          loadedImage = img;\n          document.getElementById('image-thumb').src = evt.target.result;\n          document.getElementById('thumb-filename').innerText = file.name;\n          document.getElementById('thumb-dimensions').innerText = img.width + ' x ' + img.height + ' px';\n          document.getElementById('thumb-area').style.display = 'flex';\n          updateModel();\n        };\n        img.src = evt.target.result;\n      };\n      reader.readAsDataURL(file);\n    }\n\n    function loadSampleImage() {\n      const canvas = document.getElementById('proc-canvas');\n      canvas.width = 256;\n      canvas.height = 256;\n      const ctx = canvas.getContext('2d');\n\n      ctx.fillStyle = '#ffffff';\n      ctx.fillRect(0, 0, 256, 256);\n\n      // Cute Puppy Silhouette\n      ctx.fillStyle = '#1e2230';\n      ctx.beginPath();\n      ctx.arc(128, 120, 56, 0, Math.PI * 2);\n      ctx.fill();\n\n      ctx.beginPath();\n      ctx.ellipse(78, 85, 22, 45, -0.4, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.beginPath();\n      ctx.ellipse(178, 85, 22, 45, 0.4, 0, Math.PI * 2);\n      ctx.fill();\n\n      ctx.fillStyle = '#ffffff';\n      ctx.beginPath();\n      ctx.ellipse(128, 138, 28, 22, 0, 0, Math.PI * 2);\n      ctx.fill();\n\n      ctx.fillStyle = '#000000';\n      ctx.beginPath();\n      ctx.arc(128, 126, 9, 0, Math.PI * 2);\n      ctx.fill();\n\n      ctx.beginPath();\n      ctx.arc(104, 108, 7, 0, Math.PI * 2);\n      ctx.arc(152, 108, 7, 0, Math.PI * 2);\n      ctx.fill();\n\n      const img = new Image();\n      img.onload = function() {\n        loadedImage = img;\n        document.getElementById('image-thumb').src = canvas.toDataURL();\n        document.getElementById('thumb-filename').innerText = 'sample_dog_tag.png';\n        document.getElementById('thumb-dimensions').innerText = '256 x 256 px';\n        document.getElementById('thumb-area').style.display = 'flex';\n        updateModel();\n      };\n      img.src = canvas.toDataURL();\n    }\n\n    function processImageToHeightmap() {\n      if (!loadedImage) return;\n\n      const canvas = document.getElementById('proc-canvas');\n      canvas.width = gridRes;\n      canvas.height = gridRes;\n      const ctx = canvas.getContext('2d');\n\n      ctx.drawImage(loadedImage, 0, 0, gridRes, gridRes);\n\n      // Draw embossed text if enabled\n      const textToggle = document.getElementById('param-text-toggle').checked;\n      if (textToggle) {\n        const line1 = document.getElementById('param-text-line1').value.trim();\n        const line2 = document.getElementById('param-text-line2').value.trim();\n\n        if (line1 || line2) {\n          ctx.fillStyle = '#111111';\n          ctx.textAlign = 'center';\n          ctx.textBaseline = 'middle';\n          \n          if (line1) {\n            ctx.font = 'bold 13px Pretendard, sans-serif';\n            ctx.fillText(line1, gridRes / 2, gridRes - 26);\n          }\n          if (line2) {\n            ctx.font = '600 10px JetBrains Mono, monospace';\n            ctx.fillText(line2, gridRes / 2, gridRes - 13);\n          }\n        }\n      }\n\n      const imgData = ctx.getImageData(0, 0, gridRes, gridRes);\n      const data = imgData.data;\n\n      const contrast = parseFloat(document.getElementById('param-contrast').value);\n      const invert = document.getElementById('param-invert').checked;\n      const removeBg = document.getElementById('param-remove-bg').checked;\n\n      heightmapData = new Float32Array(gridRes * gridRes);\n\n      for (let y = 0; y < gridRes; y++) {\n        for (let x = 0; x < gridRes; x++) {\n          const idx = (y * gridRes + x) * 4;\n          const r = data[idx];\n          const g = data[idx + 1];\n          const b = data[idx + 2];\n          const a = data[idx + 3] / 255;\n\n          let lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;\n\n          if (removeBg) {\n            if (a < 0.2 || (r > 240 && g > 240 && b > 240)) {\n              lum = invert ? 1.0 : 0.0;\n            }\n          }\n\n          lum = (lum - 0.5) * contrast + 0.5;\n          lum = Math.max(0, Math.min(1, lum));\n\n          if (invert) {\n            lum = 1.0 - lum;\n          }\n\n          heightmapData[y * gridRes + x] = lum;\n        }\n      }\n    }\n\n    function updateModel() {\n      const width = parseFloat(document.getElementById('param-width').value);\n      const baseThick = parseFloat(document.getElementById('param-base-thick').value);\n      const reliefHeight = parseFloat(document.getElementById('param-relief-height').value);\n      const rimHeight = parseFloat(document.getElementById('param-rim-height').value);\n      const holeDia = parseFloat(document.getElementById('param-hole-dia').value);\n      const smooth = parseFloat(document.getElementById('param-smooth').value);\n\n      document.getElementById('val-width').innerText = width + ' mm';\n      document.getElementById('val-base-thick').innerText = baseThick.toFixed(1) + ' mm';\n      document.getElementById('val-relief-height').innerText = reliefHeight.toFixed(1) + ' mm';\n      document.getElementById('val-rim-height').innerText = rimHeight.toFixed(1) + ' mm';\n      document.getElementById('val-hole-dia').innerText = holeDia.toFixed(1) + ' mm';\n      document.getElementById('val-smooth').innerText = smooth.toFixed(1);\n      document.getElementById('val-contrast').innerText = document.getElementById('param-contrast').value + 'x';\n\n      processImageToHeightmap();\n\n      while (mainMeshGroup.children.length > 0) {\n        const obj = mainMeshGroup.children[0];\n        if (obj.geometry) obj.geometry.dispose();\n        if (obj.material) obj.material.dispose();\n        mainMeshGroup.remove(obj);\n      }\n\n      // Base Plate\n      const baseMesh = buildBaseMesh(width, baseThick, currentShape, currentLoopPos, holeDia);\n      mainMeshGroup.add(baseMesh);\n\n      // Relief Mesh\n      if (heightmapData) {\n        const reliefMesh = buildReliefMesh(width, baseThick, reliefHeight, currentShape);\n        if (reliefMesh) mainMeshGroup.add(reliefMesh);\n      }\n\n      // Rim Mesh\n      if (rimHeight > 0 && currentShape === 'circle') {\n        const rimMesh = buildRimMesh(width, baseThick, rimHeight);\n        if (rimMesh) mainMeshGroup.add(rimMesh);\n      }\n\n      // Update Info\n      const totalH = (baseThick + reliefHeight).toFixed(1);\n      document.getElementById('stat-dimensions').innerText = width.toFixed(1) + ' x ' + width.toFixed(1) + ' x ' + totalH + ' mm';\n      \n      const volCm3 = (width * width * baseThick * 0.75) / 1000;\n      const weightG = (volCm3 * 1.24).toFixed(1);\n      document.getElementById('stat-weight').innerText = '~' + weightG + ' g';\n      const estMin = Math.max(8, Math.round(weightG * 3.2));\n      document.getElementById('stat-time').innerText = '~' + estMin + '분 (P1S)';\n\n      applyMaterialToGroup();\n    }\n\n    function buildBaseMesh(width, thickness, shape, loopPos, holeDia) {\n      const shapePath = new THREE.Shape();\n      const half = width / 2;\n\n      if (shape === 'circle') {\n        shapePath.absarc(0, 0, half, 0, Math.PI * 2, false);\n      } else if (shape === 'rounded') {\n        const r = half * 0.35;\n        shapePath.moveTo(-half + r, -half);\n        shapePath.lineTo(half - r, -half);\n        shapePath.quadraticCurveTo(half, -half, half, -half + r);\n        shapePath.lineTo(half, half - r);\n        shapePath.quadraticCurveTo(half, half, half - r, half);\n        shapePath.lineTo(-half + r, half);\n        shapePath.quadraticCurveTo(-half, half, -half, half - r);\n        shapePath.lineTo(-half, -half + r);\n        shapePath.quadraticCurveTo(-half, -half, -half + r, -half);\n      } else if (shape === 'bone') {\n        const w = half * 0.85;\n        const h = half * 0.45;\n        const r = half * 0.28;\n        shapePath.moveTo(-w, -h);\n        shapePath.bezierCurveTo(-w - r, -h - r, -w - r, -h + r, -w, -h * 0.1);\n        shapePath.bezierCurveTo(-w - r, h - r, -w - r, h + r, -w, h);\n        shapePath.lineTo(w, h);\n        shapePath.bezierCurveTo(w + r, h + r, w + r, h - r, w, h * 0.1);\n        shapePath.bezierCurveTo(w + r, -h + r, w + r, -h - r, w, -h);\n        shapePath.closePath();\n      } else if (shape === 'heart') {\n        const s = half * 0.85;\n        shapePath.moveTo(0, s * 0.4);\n        shapePath.bezierCurveTo(s * 0.5, s * 0.9, s, s * 0.5, s * 0.5, 0);\n        shapePath.bezierCurveTo(s * 0.25, -s * 0.5, 0, -s * 0.8, 0, -s);\n        shapePath.bezierCurveTo(0, -s * 0.8, -s * 0.25, -s * 0.5, -s * 0.5, 0);\n        shapePath.bezierCurveTo(-s, s * 0.5, -s * 0.5, s * 0.9, 0, s * 0.4);\n      } else { // rect\n        shapePath.moveTo(-half, -half);\n        shapePath.lineTo(half, -half);\n        shapePath.lineTo(half, half);\n        shapePath.lineTo(-half, half);\n        shapePath.closePath();\n      }\n\n      if (loopPos === 'top' || loopPos === 'both') {\n        const loopRadius = holeDia * 0.95;\n        const loopY = half + loopRadius * 0.75;\n        const holePath = new THREE.Path();\n        holePath.absarc(0, loopY, holeDia / 2, 0, Math.PI * 2, true);\n        shapePath.holes.push(holePath);\n      }\n\n      const geo = new THREE.ExtrudeGeometry(shapePath, {\n        depth: thickness,\n        bevelEnabled: true,\n        bevelThickness: 0.35,\n        bevelSize: 0.25,\n        bevelSegments: 2\n      });\n      geo.computeVertexNormals();\n      return new THREE.Mesh(geo, getActiveMaterial());\n    }\n\n    function buildReliefMesh(width, baseThick, reliefH, shape) {\n      const segs = gridRes - 1;\n      const geo = new THREE.PlaneGeometry(width * 0.88, width * 0.88, segs, segs);\n      const pos = geo.attributes.position;\n      const half = width / 2;\n\n      for (let i = 0; i < pos.count; i++) {\n        const x = pos.getX(i);\n        const y = pos.getY(i);\n        const u = (x / (width * 0.88) + 0.5);\n        const v = (y / (width * 0.88) + 0.5);\n\n        const gx = Math.min(gridRes - 1, Math.max(0, Math.floor(u * gridRes)));\n        const gy = Math.min(gridRes - 1, Math.max(0, Math.floor((1 - v) * gridRes)));\n        const hVal = heightmapData[gy * gridRes + gx] || 0;\n\n        let inside = true;\n        const dist = Math.sqrt(x * x + y * y);\n        if (shape === 'circle' && dist > (half * 0.85)) inside = false;\n\n        const z = inside ? (hVal * reliefH) : 0;\n        pos.setZ(i, z);\n      }\n\n      geo.computeVertexNormals();\n      const mesh = new THREE.Mesh(geo, getActiveMaterial());\n      mesh.position.z = baseThick + 0.05;\n      mesh.castShadow = true;\n      return mesh;\n    }\n\n    function buildRimMesh(width, baseThick, rimH) {\n      const r = (width / 2) * 0.95;\n      const rimGeo = new THREE.RingGeometry(r - 1.2, r, 48);\n      const rimMesh = new THREE.Mesh(rimGeo, getActiveMaterial());\n      rimMesh.position.z = baseThick + 0.06;\n      return rimMesh;\n    }\n\n    function getActiveMaterial() {\n      if (currentMaterialMode === 'gold') {\n        return new THREE.MeshStandardMaterial({\n          color: 0xd4af37,\n          roughness: 0.28,\n          metalness: 0.85,\n          wireframe: isWireframe\n        });\n      } else if (currentMaterialMode === 'litho') {\n        return new THREE.MeshPhysicalMaterial({\n          color: 0xf5f6f8,\n          roughness: 0.35,\n          transmission: 0.75,\n          thickness: 2.5,\n          wireframe: isWireframe\n        });\n      } else { // Matt PLA\n        return new THREE.MeshStandardMaterial({\n          color: 0x3b82f6,\n          roughness: 0.45,\n          metalness: 0.05,\n          wireframe: isWireframe\n        });\n      }\n    }\n\n    function applyMaterialToGroup() {\n      const mat = getActiveMaterial();\n      mainMeshGroup.traverse((child) => {\n        if (child.isMesh) {\n          child.material = mat;\n          child.castShadow = true;\n          child.receiveShadow = true;\n        }\n      });\n    }\n\n    function setMaterial(mode) {\n      currentMaterialMode = mode;\n      document.querySelectorAll('.vp-controls .vp-btn').forEach(b => b.classList.remove('active'));\n      document.getElementById('mat-' + mode).classList.add('active');\n      applyMaterialToGroup();\n    }\n\n    function toggleWireframe() {\n      isWireframe = !isWireframe;\n      document.getElementById('mat-wire').classList.toggle('active', isWireframe);\n      applyMaterialToGroup();\n    }\n\n    function resetCamera() {\n      camera.position.set(0, -55, 60);\n      controls.target.set(0, 0, 0);\n      controls.update();\n    }\n\n    function setShape(s) {\n      currentShape = s;\n      document.querySelectorAll('.segmented-control .seg-btn').forEach(b => b.classList.remove('active'));\n      const btn = document.getElementById('shape-' + s);\n      if (btn) btn.classList.add('active');\n      debouncedUpdate();\n    }\n\n    function setLoopPos(pos) {\n      currentLoopPos = pos;\n      document.getElementById('loop-top').classList.toggle('active', pos === 'top');\n      document.getElementById('loop-both').classList.toggle('active', pos === 'both');\n      document.getElementById('loop-none').classList.toggle('active', pos === 'none');\n      document.getElementById('loop-params-group').style.display = (pos === 'none') ? 'none' : 'block';\n      debouncedUpdate();\n    }\n\n    function applyPreset(type) {\n      document.querySelectorAll('.preset-grid .preset-btn').forEach(b => b.classList.remove('active'));\n      event.currentTarget.classList.add('active');\n\n      if (type === 'pet-circle') {\n        setShape('circle');\n        setLoopPos('top');\n        document.getElementById('param-width').value = 40;\n        document.getElementById('param-base-thick').value = 2.0;\n        document.getElementById('param-relief-height').value = 1.4;\n        document.getElementById('param-rim-height').value = 0.8;\n      } else if (type === 'dog-bone') {\n        setShape('bone');\n        setLoopPos('top');\n        document.getElementById('param-width').value = 52;\n        document.getElementById('param-base-thick').value = 2.2;\n        document.getElementById('param-relief-height').value = 1.2;\n        document.getElementById('param-rim-height').value = 0;\n      } else if (type === 'heart-tag') {\n        setShape('heart');\n        setLoopPos('top');\n        document.getElementById('param-width').value = 42;\n        document.getElementById('param-base-thick').value = 2.0;\n        document.getElementById('param-relief-height').value = 1.3;\n        document.getElementById('param-rim-height').value = 0;\n      } else if (type === 'lithophane') {\n        setShape('rect');\n        setLoopPos('none');\n        setMaterial('litho');\n        document.getElementById('param-width').value = 60;\n        document.getElementById('param-base-thick').value = 0.8;\n        document.getElementById('param-relief-height').value = 2.2;\n        document.getElementById('param-invert').checked = true;\n      } else if (type === 'rect-tag') {\n        setShape('rounded');\n        setLoopPos('top');\n        document.getElementById('param-width').value = 45;\n        document.getElementById('param-base-thick').value = 2.0;\n        document.getElementById('param-relief-height').value = 1.4;\n      } else if (type === 'high-relief') {\n        setShape('circle');\n        setLoopPos('top');\n        document.getElementById('param-width').value = 45;\n        document.getElementById('param-base-thick').value = 2.4;\n        document.getElementById('param-relief-height').value = 2.8;\n      }\n      debouncedUpdate();\n    }\n\n    function resetDefaults() {\n      applyPreset('pet-circle');\n    }\n\n    function openBambuGuide() {\n      document.getElementById('guide-modal').style.display = 'flex';\n    }\n\n    function closeBambuGuide(e) {\n      if (e && e.target !== e.currentTarget && !e.target.classList.contains('modal-close')) return;\n      document.getElementById('guide-modal').style.display = 'none';\n    }\n\n    function exportSTL() {\n      if (!mainMeshGroup) return;\n\n      const exporter = new THREE.STLExporter();\n      const result = exporter.parse(mainMeshGroup, { binary: true });\n\n      const blob = new Blob([result], { type: 'application/octet-stream' });\n      const link = document.createElement('a');\n      const filename = 'BambuP1S_' + currentShape + '_tag_' + Date.now() + '.stl';\n      link.href = URL.createObjectURL(blob);\n      link.download = filename;\n      link.click();\n      URL.revokeObjectURL(link.href);\n    }\n\n    window.addEventListener('DOMContentLoaded', init3D);\n  </script>\n</body>\n</html>\n";

export async function onRequestGet(context) {
  return new Response(HTML_CONTENT, {
    status: 200,
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-cache, no-store, must-revalidate'
    }
  });
}
